.ui-stage {
      display: grid;
      gap: 0.75rem;
      padding: 1rem;
      border: 1px dashed var(--is-border);
      border-radius: var(--is-radius-md, 8px);
      background: color-mix(in srgb, var(--is-control-bg) 80%, transparent);
    }
    .ui-stage__meta {
      font-size: 0.85em;
      color: var(--is-text-muted, var(--is-text));
      opacity: 0.85;
    }
    demo-card {
      display: block;
      padding: 0.85rem 1rem;
      border-radius: 8px;
      border: 1px solid var(--is-border);
      background: var(--is-bg);
      color: var(--is-text);
    }
    demo-card[data-tone="brand"] {
      border-color: color-mix(in srgb, var(--is-accent) 55%, var(--is-border));
    }

